module freq_diveven (
	input clk,rst_n,
	output clk_div,
	reg [3:0] cnt,
	reg clk_div_reg
	);

	parameter NUM_DIV = 4'd6;
	//wire [3:0] cnt_next;
	wire [3:0] cnt_mid;
	assign cnt_mid = NUM_DIV/2 - 1;

	always@(posedge clk or negedge rst_n) begin
		if(!rst_n) begin
			cnt <= 4'd0;
			clk_div_reg <= 1'b0;
		end
		else if(cnt == cnt_mid) begin
			cnt <= 4'd0;
			clk_div_reg <= ~clk_div_reg;
		end
		else begin
			cnt <= cnt + 1;
		end

	end

	assign clk_div = clk_div_reg;


endmodule
